#include "breeze/common.h"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <vector>

namespace {

constexpr int kHeadDim = 128;
constexpr int kHeads = 16;
constexpr int kKvHeads = 8;

struct ProbeCase {
    const char * name;
    int n_q;
    int n_kv;
    int q_offset;
};

static float value(size_t i, float phase) {
    return 0.2f * std::sin(static_cast<float>(i) * 0.017f + phase);
}

static bool compare(const std::vector<float> & reference, const std::vector<float> & candidate,
                   double & max_abs, double & relative_l2) {
    if (reference.size() != candidate.size()) return false;
    double ref_l2 = 0.0;
    double delta_l2 = 0.0;
    max_abs = 0.0;
    for (size_t i = 0; i < reference.size(); ++i) {
        if (!std::isfinite(reference[i]) || !std::isfinite(candidate[i])) return false;
        const double delta = static_cast<double>(candidate[i]) - reference[i];
        max_abs = std::max(max_abs, std::abs(delta));
        ref_l2 += static_cast<double>(reference[i]) * reference[i];
        delta_l2 += delta * delta;
    }
    relative_l2 = std::sqrt(delta_l2) / std::max(std::sqrt(ref_l2), 1.0e-12);
    return true;
}

} // namespace

int main() {
    const ProbeCase cases[] = {
        {"query_kv1", 1, 1, 0},
        {"prefill_q3_kv3", 3, 3, 0},
        {"query_context4", 1, 4, 3},
        {"prefill_q63_kv63", 63, 63, 0},
        {"query_context64", 1, 64, 63},
    };

    breeze::Backend backend;
    backend.init(false);
    bool all_finite = true;
    for (const ProbeCase & test : cases) {
        breeze::Graph graph(8192);
        std::vector<float> q_data(static_cast<size_t>(kHeadDim) * kHeads * test.n_q);
        std::vector<float> k_data(static_cast<size_t>(kHeadDim) * kKvHeads * test.n_kv);
        std::vector<float> v_data(static_cast<size_t>(kHeadDim) * kKvHeads * test.n_kv);
        for (size_t i = 0; i < q_data.size(); ++i) q_data[i] = value(i, 0.1f);
        for (size_t i = 0; i < k_data.size(); ++i) k_data[i] = value(i, 0.7f);
        for (size_t i = 0; i < v_data.size(); ++i) v_data[i] = value(i, 1.3f);

        ggml_tensor * q = graph.input_f32(q_data, kHeadDim, kHeads, test.n_q);
        ggml_tensor * k = graph.input_f32(k_data, kHeadDim, kKvHeads, test.n_kv);
        ggml_tensor * v = graph.input_f32(v_data, kHeadDim, kKvHeads, test.n_kv);
        ggml_tensor * mask = graph.input_f32(
            breeze::build_causal_mask(test.n_q, test.n_kv, test.q_offset, 0), test.n_kv, test.n_q);

        ggml_tensor * reference = breeze::attention(
            graph.ctx, q, k, v, mask, 1.0f / std::sqrt(static_cast<float>(kHeadDim)), kHeads, kKvHeads);
        ggml_tensor * flash_mask = ggml_cast(graph.ctx, mask, GGML_TYPE_F16);
        ggml_tensor * flash_q = ggml_permute(graph.ctx, q, 0, 2, 1, 3);
        ggml_tensor * flash_k = ggml_permute(graph.ctx, k, 0, 2, 1, 3);
        ggml_tensor * flash_v = ggml_permute(graph.ctx, v, 0, 2, 1, 3);
        ggml_tensor * flash = ggml_flash_attn_ext(
            graph.ctx, flash_q, flash_k, flash_v, flash_mask,
            1.0f / std::sqrt(static_cast<float>(kHeadDim)), 0.0f, 0.0f);
        ggml_flash_attn_ext_set_prec(flash, GGML_PREC_F32);
        flash = ggml_reshape_2d(graph.ctx, flash, kHeadDim * kHeads, test.n_q);

        graph.mark_output(reference);
        graph.mark_output(flash);
        graph.compute(backend, flash);
        const std::vector<float> reference_data = breeze::tensor_to_f32(reference);
        const std::vector<float> flash_data = breeze::tensor_to_f32(flash);
        double max_abs = 0.0;
        double relative_l2 = 0.0;
        const bool finite = compare(reference_data, flash_data, max_abs, relative_l2);
        all_finite = all_finite && finite;
        std::printf("case=%s shape=%zu finite=%s max_abs=%.9g relative_l2=%.9g\n",
                    test.name, reference_data.size(), finite ? "true" : "false", max_abs, relative_l2);
    }
    backend.free();
    return all_finite ? 0 : 1;
}
